def is_bachata(S):
    """
    Checks if a given set S is a Bachata set.
    S must be a subset of {0, 1, 2, ...}.
    Since sets are often represented finitely in simulation, this check is limited
    to the elements present in S.
    """
    if not S:
        return False

    # Condition 1: 0 must be in S
    if 0 not in S:
        return False

    # Condition 2: For each element n in S, n+11 and n+20 must be in S.
    # We iterate over a list copy to avoid modification issues if the set were dynamic,
    # though here we only read from S.
    for n in S:
        if n + 11 not in S:
            print(f"Failure: n={n}. n+11={n+11} is missing.")
            return False
        if n + 20 not in S:
            print(f"Failure: n={n}. n+20={n+20} is missing.")
            return False

    # Note: This verification assumes S is closed under +11 and +20 within its definition.
    # If S is finite, this check is insufficient to prove Bachata status globally,
    # but it verifies the local condition for all elements present.
    return True

# --- Test Cases ---

# Test Case 1: The minimal Bachata set (S = {0}) - Fails because 11 and 20 are missing
S1 = {0}
print(f"Testing S1 = {S1}: Bachata? {is_bachata(S1)}")
print("-" * 20)

# Test Case 2: A structure generated by 0, 11, 20, 31, 40, 51, 60, ...
# Let's generate a small finite set that *should* satisfy the conditions internally.
# Start with {0}
# n=0 -> add 11, 20. S = {0, 11, 20}
# n=11 -> add 22, 31. S = {0, 11, 20, 22, 31}
# n=20 -> add 31 (already there), 40. S = {0, 11, 20, 22, 31, 40}
# n=22 -> add 33, 42. S = {0, 11, 20, 22, 31, 40, 33, 42}
# n=31 -> add 42 (already there), 51. S = {0, 11, 20, 22, 31, 40, 33, 42, 51}
S2 = {0, 11, 20, 22, 31, 40, 33, 42, 51}
print(f"Testing S2 (finite valid structure): Bachata? {is_bachata(S2)}")
print("-" * 20)

# Test Case 3: A failing case (Missing 11)
S3 = {0, 20}
print(f"Testing S3 = {S3}: Bachata? {is_bachata(S3)}")
print("-" * 20)

# Test Case 4: A failing case (0 missing)
S4 = {11, 20}
print(f"Testing S4 = {S4}: Bachata? {is_bachata(S4)}")

import numpy as np

# Frobenius number g(11, 20) = 11*20 - 11 - 20 = 189.
# All numbers > 189 are in S_min.
LIMIT = 200

# Generate S_min = {11x + 20y | x >= 0, y >= 0} up to LIMIT
S_min = set()
for x in range(LIMIT // 11 + 1):
    for y in range(LIMIT // 20 + 1):
        n = 11 * x + 20 * y
        if n <= LIMIT:
            S_min.add(n)

# Identify the gaps R = {n <= 189 | n not in S_min}
R = []
for n in range(190):
    if n not in S_min:
        R.append(n)

print(f"Size of R (Gaps of S_min up to 189): {len(R)}")
# print(f"R: {R}") # Too long to print
print(f"S_min size up to 199: {len(S_min)}")
